def counter_ops(ops):
    v, out = 0, []
    for op in ops:
        if op == 'inc':
            v += 1
        elif op == 'dec':
            v = max(0, v - 1)
        elif op == 'reset':
            v = 0
        else:
            out.append(v)
    return out
